<?php require_once __DIR__.'/app/core/bootstrap.php'; $title='Activities'; $rows=query("SELECT * FROM activities WHERE status IN ('active','pending') ORDER BY status='active' DESC,id DESC")->fetch_all(MYSQLI_ASSOC); require __DIR__.'/app/views/header.php'; ?>
<section class="section"><div class="section-head"><div><div class="eyebrow" style="color:var(--green)">Make the day yours</div><h2>Arusha activities</h2></div></div><div class="grid"><?php foreach($rows as $r): ?><article class="card"><div class="card-img"><img src="<?=e(media_url($r['image']))?>" alt=""></div><div class="card-body"><div class="row-between"><span class="tag <?=($r['status']!=='active'?'pending':'')?>"><?=ucfirst($r['status'])?></span><span class="muted"><?=$r['duration_hours']?>h</span></div><h3><?=e($r['name'])?></h3><p><?=e($r['description'])?></p><div class="row-between"><span class="price"><?=money((float)$r['price'])?></span><span class="muted">Optional add-on</span></div></div></article><?php endforeach; ?></div></section>
